-- Agent editorial correction, 2026-09-10. Apply only after 052; no human review implied.
BEGIN;
CREATE TEMP TABLE caption_intervention_055(question_id TEXT, indicator_id TEXT, country_iso3 TEXT, plain TEXT, expert TEXT) ON COMMIT DROP;
UPDATE question_indicators qi SET caption_plain=c.plain,caption_expert=c.expert
FROM caption_intervention_055 c WHERE qi.question_id=c.question_id AND qi.indicator_id=c.indicator_id
AND qi.country_iso3 IS NOT DISTINCT FROM c.country_iso3
AND (qi.caption_plain,qi.caption_expert) IS DISTINCT FROM (c.plain,c.expert);

UPDATE research_evidence SET finding='BEA generally obtains real fixed investment by dividing nominal investment by a price index; stocks additionally depend on depreciation.',relevance='BEA''s nominal/price identity supports the conditional direction, not a measured AI price decline. A falling matched price raises real growth relative to nominal growth; depreciation and asset coverage still prevent an inference about capital deepening.',relationship='supports' WHERE id='editorial-20260910-atomic-deflator-direction-source';
UPDATE research_evidence SET finding='BLS distinguishes output per hour, capital services and TFP. Unit labour costs are compensation per unit of output.',relevance='BLS defines capital deepening in terms of capital input relative to labour. BEA''s investment-flow construction complements that distinction: a spending increase can coexist with depreciation or faster labour growth. Neither establishes an AI productivity return.',relationship='supports' WHERE id='editorial-20260910-atomic-capital-deepening-source';
UPDATE research_evidence SET finding='BEA generally obtains real fixed investment by dividing nominal investment by a price index; stocks additionally depend on depreciation.',relevance='The BEA identity supports the need for a matched deflator; it does not supply one for Census electronic-product orders. The nominal historical comparison remains descriptive, and both directions of real change remain possible.',relationship='supports' WHERE id='editorial-20260910-atomic-orders-deflation-source';
UPDATE research_evidence SET finding='BLS distinguishes output per hour, capital services and TFP. Unit labour costs are compensation per unit of output.',relevance='BLS directly defines compensation per unit of output. The cloud-PPI methodology concerns a different service basket; comparing their percentage changes does not put labour hours and AI computations on an equivalent basis.',relationship='supports' WHERE id='editorial-20260910-atomic-ulc-definition-source';
UPDATE research_evidence SET finding='BLS distinguishes output per hour, capital services and TFP. Unit labour costs are compensation per unit of output.',relevance='BLS''s ratio identity permits both series to rise. Wage growth must be reconstructed multiplicatively from matched compensation, hours and output measures; a simple difference between two index-growth rates is not the wage measure.',relationship='supports' WHERE id='editorial-20260910-atomic-ulc-and-productivity-source';
UPDATE research_evidence SET finding='BLS distinguishes output per hour, capital services and TFP. Unit labour costs are compensation per unit of output.',relevance='BLS distinguishes capital-input and labour-productivity accounting. This supports checking different denominators, but the incompatibility of these particular OECD series still requires their own codebook. No numerical return ratio is endorsed.',relationship='context' WHERE id='editorial-20260910-atomic-capital-contributions-source';
UPDATE research_evidence SET finding='Publication and effective dates differ. Document categories contain actions beyond new obligations, and proposals must be followed through their histories.',relevance='NARA directly distinguishes publication from effective dates and exceptions. This challenges the earlier ''rules in force'' caption, but does not establish the legal status of any individual sampled document.',relationship='supports' WHERE id='editorial-20260910-atomic-publication-effective-source';
UPDATE research_evidence SET finding='Publication and effective dates differ. Document categories contain actions beyond new obligations, and proposals must be followed through their histories.',relevance='NARA describes the rulemaking sequence; a proposal-to-final-rule conversion estimate additionally requires linked actions and follow-up time. This is a statistical deduction, not a conversion rate estimated by the tutorial.',relationship='context' WHERE id='editorial-20260910-atomic-proposal-cohorts-source';
UPDATE research_evidence SET finding='The register includes a planned-systems option and warns that reporting coverage varies; planned specifications have lower confidence.',relevance='Epoch explicitly permits planned systems and describes uncertainty. IEA''s geographic and connection constraints further explain why announced power and deliverable operating supply differ. Neither source validates the status of each ingested cluster.',relationship='supports' WHERE id='editorial-20260910-atomic-capacity-status-source';
UPDATE research_evidence SET finding='The study examines cloud quality adjustment and explains that hosting is one component of the broader data-processing price index.',relevance='BLS''s cloud study identifies basket and quality-adjustment limitations. Its microprocessor study independently illustrates that hardware quality adjustment is not interchangeable with hosting-service prices. No AI-service inflation estimate is established.',relationship='supports' WHERE id='editorial-20260910-atomic-hosting-basket-source';
UPDATE research_evidence SET finding='A staggered workplace rollout reports productivity gains with substantial variation by worker experience and skill.',relevance='The AI-at-Work v2 abstract reports heterogeneous productivity gains in a specific workplace. Acemoglu''s task framework makes aggregate effects depend on affected task shares and substitution versus complementarity; positive workplace results therefore do not settle entry-level hiring or economy-wide employment.',relationship='supports' WHERE id='editorial-20260910-atomic-workplace-complementarity-source';
UPDATE research_evidence SET finding='Complementary intangible investment can delay measured productivity benefits. The authors explicitly state that such investment does not guarantee a J-curve.',relevance='The J-curve manuscript expressly rejects guaranteed payoffs. Acemoglu''s framework additionally conditions aggregate gains on task exposure and savings; workplace productivity evidence establishes possibility in one setting, not the size or timing of a national productivity acceleration.',relationship='supports' WHERE id='editorial-20260910-atomic-jcurve-not-guaranteed-source';
UPDATE research_evidence SET finding='Cash-flow statements distinguish operating cash, asset investment and financing from debt or equity.',relevance='The SEC''s separation of operating, investing and financing cash flows directly challenges the earlier assertion that capex necessarily comes from operations. Aggregate investment and venture funding describe different uses and channels, not a reconciled funding account.',relationship='supports' WHERE id='editorial-20260910-atomic-financing-versus-use-source';
UPDATE research_evidence SET finding='National electricity prices are weighted averages; Eurostat aggregates national prices using consumption weights.',relevance='Eurostat''s consumption-weighted aggregation makes composition a concrete rival explanation to bargaining power. The observed band gap can describe average prices, but identifying a volume discount requires matched contracts or a design controlling for composition.',relationship='context' WHERE id='editorial-20260910-atomic-band-composition-source';

-- Explicit comparative sources, with access limits preserved; no review events.

COMMIT;
