INSERT INTO caption_intervention_055 VALUES
('adoption','derived.sec_ai_mention_rate','USA','AI mentions in sampled US corporate annual reports.','Mentions measure disclosure and attention, not verified deployment. Changing filing coverage, search terms and the denominator can alter the share; legal liability does not turn a mention into proof of operational use.'),
('adoption','dbn.OECD.DSD_ICT_B_DF_BUSINESSES.OECD.A.G14_B.PT_ENT._T.S_GE10',NULL,'Reported business AI use in the selected OECD or EU aggregate.','The enterprise population and survey frame must be matched by year. Neither aggregate covers every business in the developed world; mirror differences require checking release dates rather than assuming one source is permanently preferred.'),
('adoption','dbn.OECD.DSD_ICT_B_DF_BUSINESSES.EU27.A.G14_B.PT_ENT._T.S_GE10',NULL,'Reported business AI use in the selected OECD or EU aggregate.','The enterprise population and survey frame must be matched by year. Neither aggregate covers every business in the developed world; mirror differences require checking release dates rather than assuming one source is permanently preferred.'),
('adoption','dbn.OECD.ict_business.KOR.ai_adoption','KOR','South Korean business AI adoption provides another national comparison.','Survey year, enterprise-size threshold and questionnaire must be matched before ranking countries; this is not a natural experiment.'),
('adoption','dbn.OECD.DSD_ICT_B_DF_BUSINESSES.OECD.A.G14_B.PT_ENT.J.S_GE10',NULL,'Reported AI use among information and communication businesses.','NACE J includes more than software and telecoms. Sector composition and survey coverage matter; sector adoption levels do not establish an adoption ceiling or speed for other industries.'),
('adoption','dbn.Eurostat.isoc_eb_ain2.A.GE10.J62_J63.E_AI_TANY.PC_ENT.EU27_2020',NULL,'Reported AI adoption in European programming and IT consultancy businesses.','This narrower EU sector motivates a hypothesis about exposure. It is not direct evidence of AI adoption in every UK information-and-communication business or an explanation of its productivity growth.'),
('adoption','dbn.Eurostat.isoc_eb_ain2.manufacturing',NULL,'Reported AI use in European manufacturing businesses.','Compare within the survey population and reference year. A lower share than information services does not identify a number of years of diffusion delay.'),
('adoption','dbn.Eurostat.isoc_eb_ai.A.GE10.C10-S951_X_K.E_AI_TNLG.PC_ENT.EU27_2020',NULL,'Businesses reporting use of AI to generate written or spoken language.','This survey category is not a count of ChatGPT customers and can include multiple technologies and delivery models.'),
('adoption','dbn.Eurostat.isoc_cicce_use.A.GE10.C10-S951_X_K.E_CC1_PANY.PC_ENT.EU27_202',NULL,'Businesses purchasing cloud services: a complementary digital-infrastructure indicator.','Purchased cloud services and AI use are separate survey measures. AI may be used through other arrangements; this share is neither a necessary ceiling on AI adoption nor an identified driver of diffusion.'),
('adoption','dbn.OECD.DSD_ICT_B_DF_BUSINESSES.OECD.A.H1_B.PT_ENT._T.S_GE10',NULL,'Businesses employing ICT specialists.','An organisational-capacity proxy, not a test of whether a firm can use AI. Outsourcing, existing software and job definitions also affect the measure.'),
('adoption','dbn.Eurostat.isoc_ske_itrcrn2.A.GE10.C10-S951_X_K.E_ITSPVAC2.PC_ENT.EU27_2',NULL,'Enterprises reporting hard-to-fill ICT-specialist vacancies.','The PC_ENT denominator is enterprises in scope, not only enterprises that attempted recruitment. Check the reference period and denominator before comparing this share with vacancy rates.'),
('adoption','wb.IT.NET.USER.ZS','USA','Internet use provides historical context for technology diffusion.','The population is individuals, unlike enterprise AI surveys. Similar-looking adoption curves do not establish a matched diffusion-speed comparison.'),
('adoption','eurostat.ai_any.ALB','ALB','Reported business AI use for the selected country.','Compare reference years, firm-size thresholds, sector coverage and survey wording before interpreting country gaps. Eurostat and OECD observations are not automatically interchangeable; this placement does not establish a harmonised ranking.'),
