INSERT INTO research_evidence (id,claim_id,source_url,source_title,source_version,locator,finding,method,limitations,relationship,relevance,access_basis,publication_stage) VALUES ('editorial-20260910-atomic-jcurve-not-guaranteed-compare-acemoglu','editorial-20260910-atomic-jcurve-not-guaranteed','https://economics.mit.edu/sites/default/files/2024-10/The%20Simple%20Macroeconomics%20of%20AI.pdf','The Simple Macroeconomics of AI','Economic Policy 2024 author-hosted published PDF, DOI 10.1093/epolic/eiae042; accessed 10 September 2026','Summary and introduction, PDF pages 1 and 3-6','The task framework links aggregate gains to affected task shares and cost savings, distinguishing automation from complementarity.','Task-based model and calibrated scenarios.','Its assumptions and forecasts are not current observed outcomes or universal country estimates.','context','Task exposure and savings condition the macro payoff; this supplies a second conditional mechanism rather than validation of a future boom.','full_text','published') ON CONFLICT(id) DO UPDATE SET finding=EXCLUDED.finding,relevance=EXCLUDED.relevance,relationship=EXCLUDED.relationship,source_version=EXCLUDED.source_version,locator=EXCLUDED.locator,access_basis=EXCLUDED.access_basis;
INSERT INTO research_evidence (id,claim_id,source_url,source_title,source_version,locator,finding,method,limitations,relationship,relevance,access_basis,publication_stage) VALUES ('editorial-20260910-atomic-jcurve-not-guaranteed-compare-ai-work','editorial-20260910-atomic-jcurve-not-guaranteed','https://arxiv.org/abs/2304.11771v2','Generative AI at Work','arXiv version 2, revised 6 November 2024; abstract accessed 10 September 2026','Version 2 abstract only','A staggered workplace rollout reports productivity gains with substantial variation by worker experience and skill.','Staggered introduction among customer-support agents, as described in the abstract.','Abstract-only review: not a full assessment of identification, and not an employment-creation estimate.','context','Workplace gains show a bounded empirical possibility. Abstract-only evidence in one setting cannot establish national timing or a guaranteed payoff.','abstract','working_paper') ON CONFLICT(id) DO UPDATE SET finding=EXCLUDED.finding,relevance=EXCLUDED.relevance,relationship=EXCLUDED.relationship,source_version=EXCLUDED.source_version,locator=EXCLUDED.locator,access_basis=EXCLUDED.access_basis;
INSERT INTO research_evidence (id,claim_id,source_url,source_title,source_version,locator,finding,method,limitations,relationship,relevance,access_basis,publication_stage) VALUES ('editorial-20260910-atomic-workplace-complementarity-compare-acemoglu','editorial-20260910-atomic-workplace-complementarity','https://economics.mit.edu/sites/default/files/2024-10/The%20Simple%20Macroeconomics%20of%20AI.pdf','The Simple Macroeconomics of AI','Economic Policy 2024 author-hosted published PDF, DOI 10.1093/epolic/eiae042; accessed 10 September 2026','Summary and introduction, PDF pages 1 and 3-6','The task framework links aggregate gains to affected task shares and cost savings, distinguishing automation from complementarity.','Task-based model and calibrated scenarios.','Its assumptions and forecasts are not current observed outcomes or universal country estimates.','context','Task-level complementarity and substitution clarify why productivity gains are not an estimate of new-worker hiring or economy-wide employment.','full_text','published') ON CONFLICT(id) DO UPDATE SET finding=EXCLUDED.finding,relevance=EXCLUDED.relevance,relationship=EXCLUDED.relationship,source_version=EXCLUDED.source_version,locator=EXCLUDED.locator,access_basis=EXCLUDED.access_basis;
INSERT INTO research_evidence (id,claim_id,source_url,source_title,source_version,locator,finding,method,limitations,relationship,relevance,access_basis,publication_stage) VALUES ('editorial-20260910-atomic-capacity-status-compare-iea-energy','editorial-20260910-atomic-capacity-status','https://www.iea.org/reports/energy-and-ai/executive-summary','Energy and AI — Executive summary','2025 report; executive summary accessed 10 September 2026','Local impacts; grid integration; uncertainty sections','The IEA identifies geographically concentrated data-centre demand and grid-connection constraints, and explores uncertain future demand scenarios.','Global energy modelling and infrastructure analysis.','Scenarios are projections; local constraints cannot be inferred from national tariff averages alone.','context','Local connection constraints distinguish proposed power capacity from deliverable operating infrastructure. This does not validate individual cluster status.','full_text','report') ON CONFLICT(id) DO UPDATE SET finding=EXCLUDED.finding,relevance=EXCLUDED.relevance,relationship=EXCLUDED.relationship,source_version=EXCLUDED.source_version,locator=EXCLUDED.locator,access_basis=EXCLUDED.access_basis;
INSERT INTO research_evidence (id,claim_id,source_url,source_title,source_version,locator,finding,method,limitations,relationship,relevance,access_basis,publication_stage) VALUES ('editorial-20260910-atomic-hosting-basket-compare-bls-chip','editorial-20260910-atomic-hosting-basket','https://www.bls.gov/opub/mlr/2018/article/a-new-approach-for-quality-adjusting-ppi-microprocessors.htm','A new approach for quality-adjusting PPI microprocessors','Monthly Labor Review, December 2018; accessed 10 September 2026','Introduction and Data and methods','Microprocessor pricing and quality changes can make matched-model and hedonic indices behave differently.','Historical hedonic and matched-model price-index comparison.','The historical microprocessor sample does not provide a current GPU or AI-task price index.','context','Hardware quality-adjustment problems are an additional reason not to treat semiconductor and hosting price indexes as a single constant-quality compute price.','full_text','published') ON CONFLICT(id) DO UPDATE SET finding=EXCLUDED.finding,relevance=EXCLUDED.relevance,relationship=EXCLUDED.relationship,source_version=EXCLUDED.source_version,locator=EXCLUDED.locator,access_basis=EXCLUDED.access_basis;
